/** Root-reviewed independent empty Source211 compilation. Metadata authority
 * only: no Native business certification, migration or application activation.
 * The explicit draft validator remains separate from the fixed contract. */
import assert from 'node:assert/strict';
import {gunzipSync} from 'node:zlib';
