import {ORDER_MERGE_DELIVERY209_SOURCE_CONTRACT as E209} from './order-merge-delivery209-source-contract.mjs';

const freeze=v=>{if(v&&typeof v==='object'){Object.values(v).forEach(freeze);Object.freeze(v);}return v;};
export const RETURN_CREDIT211_DRAFT_STATUS=freeze({status:'DRAFT_INVERSE_ONLY_NOT_SOURCE_AUTHORITY',source_compilation_proven:false,native_certification:false,application_activation:false,business_acceptance:false});
export const RETURN_CREDIT211_SOURCE_STATUS=freeze({status:'SOURCE_COMPILED_METADATA_ONLY_NOT_NATIVE_CERTIFIED',source_compilation_proven:true,native_certification:false,application_activation:false,business_acceptance:false});
const kinds=['relation','column','constraint','index','policy','trigger','function','type'];
const id=r=>r.kind+'\0'+r.key;
const exact=(v,keys)=>assert.deepEqual(Object.keys(v??{}).sort(),[...keys].sort(),'211 exact fields');
const functionKeys=['acl','acl_null','argument_modes','argument_names','arguments','binary','config','cost','defaults','definition','kind','language','leakproof','owner','parallel','result','returns_set','rows','security_definer','source','strict','support','variadic','volatility'];
const signatures=['public.return_credit206_fingerprint()','public.return_credit206_issue(pid uuid, b jsonb, uid uuid, kid uuid)','public.return_credit206_source(did uuid, selected_return uuid)'];
const fkName='return_credit206_receipts_tenant_id_return_receipt_id_fkey';
const fkKey='public.return_credit206_receipts.'+fkName;
assert(E207.source_compilation_proven&&E207.independent_empty_source_database&&E207.old_certificate_rows_not_updated);
const original=key=>{const rows=E207.additions.filter(r=>r.key===key);assert.equal(rows.length,1,'211 literal207 predecessor required');return rows[0];};
const functions=signatures.map(original),constraint=original(fkKey);
const ri=E207.additions.filter(r=>r.kind==='trigger'&&r.value.constraint===fkName);
assert.equal(ri.length,4);
const child=ri.filter(r=>r.key.startsWith('public.return_credit206_receipts.'));
const removed=ri.filter(r=>r.key.startsWith('public.catalog_stock_return_receipts.'));
assert.equal(child.length,2);assert.equal(removed.length,2);
const before=[constraint,...functions,...child].sort((a,b)=>id(a)<id(b)?-1:1);
for(const e of [E208,E209])for(const r of [...before,...removed]){
 assert(!e.changes.some(c=>c.kind===r.kind&&c.key===r.key),'211 predecessor unexpectedly changed after207');
 assert(!e.additions.some(c=>c.kind===r.kind&&c.key===r.key),'211 predecessor unexpectedly replaced after207');
}
export const RETURN_CREDIT211_DRAFT_PREDECESSOR=freeze({stage:209,changes:before,removed,required_retarget_parent_triggers:removed.map(r=>({...r,key:r.key.replace('public.catalog_stock_return_receipts.','public.return_credit211_acceptances.')}))});

function canonical(v,depth=0,budget={nodes:0}){
 assert(depth<=64&&++budget.nodes<=1000000,'211 JSON bounds');
 if(v===null||typeof v==='string'||typeof v==='boolean')return v;
 if(typeof v==='number'){assert(Number.isFinite(v),'211 finite number');return v;}
 assert(v&&typeof v==='object','211 plain JSON');
 const descriptors=Object.getOwnPropertyDescriptors(v);
 assert(Object.values(descriptors).every(d=>!d.get&&!d.set),'211 no accessors');
 if(Array.isArray(v)){
  assert(v.length<=100000&&Object.keys(v).length===v.length,'211 dense bounded arrays');
  return Array.from({length:v.length},(_,i)=>{assert(Object.hasOwn(v,i),'211 dense arrays');return canonical(v[i],depth+1,budget);});
 }
 assert([Object.prototype,null].includes(Object.getPrototypeOf(v)),'211 plain object');
 return Object.fromEntries(Object.keys(v).sort().map(k=>[k,canonical(v[k],depth+1,budget)]));
}
export function normalizeReturnCredit211DraftRecords(value){
 assert(Array.isArray(value)&&value.length<=100000,'211 bounded records');
 const rows=canonical(value);let previous='';
 for(const row of rows){
  exact(row,['kind','key','value']);assert(typeof row.kind==='string'&&row.kind.length>0&&typeof row.key==='string'&&row.key.length>0&&row.key.length<=4096&&!row.key.includes('\0'));
  assert(row.value&&typeof row.value==='object'&&!Array.isArray(row.value));
  assert(id(row)>previous,'211 duplicate or unordered record');previous=id(row);
 }
 return rows;
}
function fullFunction(value){
 exact(value,functionKeys);
 assert(typeof value.source==='string'&&value.source.length>0&&typeof value.definition==='string'&&value.definition.includes(value.source),'211 complete function text');
}
/** All candidate-owned additions, including opposite-side RI on old relations.
 * Unknown incoming dependencies also remain poison, never silently stripped. */
export function isReturnCredit211DraftFootprint(row){
 return /(?:^|\.)_?return_credit211_/.test(row.key)
  ||(row.kind==='trigger'&&[row.value.constraint,row.value.constraint_relation].some(v=>typeof v==='string'&&v.startsWith('return_credit211_')))
  ||(row.kind==='constraint'&&row.value.kind==='f'&&typeof row.value.definition==='string'&&/\bREFERENCES\s+(?:public\.)?return_credit211_/.test(row.value.definition));
}
/** The explicit argument remains untrusted candidate data: validation of shape
 * and literal BEFORE is not independent source compilation of AFTER. */
export function validateReturnCredit211DraftContract(value){
 assert(value,'211 candidate expectation required; compiled211 contract not published');
 const e=canonical(value);exact(e,['schema','source_compilation_proven','native_certification','application_activation','business_acceptance','additions','changes','removed']);
 assert.equal(e.schema,'source211-return-credit148-exact-inverse-draft/v1');
 for(const key of ['source_compilation_proven','native_certification','application_activation','business_acceptance'])assert.equal(e[key],false,'211 draft cannot claim acceptance');
 e.additions=normalizeReturnCredit211DraftRecords(e.additions);e.removed=normalizeReturnCredit211DraftRecords(e.removed);
 assert.deepEqual(e.removed,canonical(removed),'211 exact two removed parent RI BEFORE records');
 assert(Array.isArray(e.changes)&&e.changes.length===before.length,'211 exact six descriptor changes');
 assert.deepEqual(e.changes.map(c=>c.kind+'\0'+c.key),before.map(id),'211 closed change roster');
 for(let i=0;i<before.length;i++){
  const c=e.changes[i],b=before[i];exact(c,['kind','key','before','after']);assert.deepEqual(c.before,canonical(b.value),'211 full literal209 BEFORE');
  assert.notDeepEqual(c.before,c.after,'211 changed descriptor required');
  if(c.kind==='function'){
   fullFunction(c.after);
   assert.deepEqual(Object.fromEntries(Object.entries(c.after).filter(([k])=>!['source','definition'].includes(k))),Object.fromEntries(Object.entries(c.before).filter(([k])=>!['source','definition'].includes(k))),'211 preserve all22 nontext function fields');
   assert.equal(c.before.definition.split(c.before.source).length,2);
   assert.equal(c.after.definition,c.before.definition.replace(c.before.source,()=>c.after.source),'211 complete definition/body replacement');
  }else if(c.kind==='constraint')assert.deepEqual(c.after,{...c.before,definition:'FOREIGN KEY (tenant_id, return_receipt_id) REFERENCES return_credit211_acceptances(tenant_id, id)'},'211 exact typed-parent FK');
  else assert.deepEqual(c.after,{...c.before,constraint_relation:'return_credit211_acceptances'},'211 exact retargeted child RI');
 }
 const touched=new Set([...before,...removed].map(id));
 assert(e.additions.length>0&&e.additions.every(r=>kinds.includes(r.kind)&&isReturnCredit211DraftFootprint(r)&&!touched.has(id(r))),'211 own eight-kind additions only');
 assert.deepEqual([...new Set(e.additions.map(r=>r.kind))].sort(),[...kinds].sort(),'211 complete eight-kind candidate');
 for(const row of e.additions)if(row.kind==='function')fullFunction(row.value);
 for(const row of RETURN_CREDIT211_DRAFT_PREDECESSOR.required_retarget_parent_triggers)assert.deepEqual(e.additions.find(r=>id(r)===id(row)),canonical(row),'211 exact new target parent RI');
 return freeze(e);
}

